class Solution {
public:
    TreeNode* lca(TreeNode* node, int p, int q) {
        if (!node || node->val == p || node->val == q) return node;
        TreeNode* left = lca(node->left, p, q);
        TreeNode* right = lca(node->right, p, q);
        if (left && right) return node;
        return left ? left : right;
    }
    int dist(TreeNode* node, int target, int d) {
        if (!node) return -1;
        if (node->val == target) return d;
        int left = dist(node->left, target, d + 1);
        if (left != -1) return left;
        return dist(node->right, target, d + 1);
    }
    int findDistance(TreeNode* root, int p, int q) {
        if (p == q) return 0;
        TreeNode* common = lca(root, p, q);
        return dist(common, p, 0) + dist(common, q, 0);
    }
};

class Solution {
    private TreeNode lca(TreeNode node, int p, int q) {
        if (node == null || node.val == p || node.val == q) return node;
        TreeNode left = lca(node.left, p, q);
        TreeNode right = lca(node.right, p, q);
        if (left != null && right != null) return node;
        return left != null ? left : right;
    }
    private int dist(TreeNode node, int target, int d) {
        if (node == null) return -1;
        if (node.val == target) return d;
        int left = dist(node.left, target, d + 1);
        if (left != -1) return left;
        return dist(node.right, target, d + 1);
    }
    public int findDistance(TreeNode root, int p, int q) {
        if (p == q) return 0;
        TreeNode common = lca(root, p, q);
        return dist(common, p, 0) + dist(common, q, 0);
    }
}

var findDistance = function(root, p, q) {
    if (p === q) return 0;
    function lca(node) {
        if (!node || node.val === p || node.val === q) return node;
        const left = lca(node.left);
        const right = lca(node.right);
        if (left && right) return node;
        return left || right;
    }
    const common = lca(root);
    function dist(node, target, d) {
        if (!node) return -1;
        if (node.val === target) return d;
        const left = dist(node.left, target, d + 1);
        if (left !== -1) return left;
        return dist(node.right, target, d + 1);
    }
    return dist(common, p, 0) + dist(common, q, 0);
};
